namespace ghidra.feature.vt.gui.actions;






using docking;
using docking;
using docking.action;
using docking.widgets;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.feature.vt.gui.task;
using ghidra.util;
using ghidra.util.task;

public class RemoveMatchTagAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.TAG_MENU_GROUP;
	private static readonly Icon EDIT_TAG_ICON =
		new GIcon("icon.version.tracking.action.match.tag.remove");
	private static readonly string ACTION_NAME = "Remove VTMatch Tags";

	private int tagCount = 0;

	public RemoveMatchTagAction() : base(ACTION_NAME, VTPlugin.OWNER)
    {

		setDescription("Remove Match Tag");
		setToolBarData(new ToolBarData(EDIT_TAG_ICON, MENU_GROUP));
		MenuData menuData = new MenuData(new string[] { "Remove Tag" }, EDIT_TAG_ICON, MENU_GROUP);
		menuData.setMenuSubGroup("2"); // after the Chooser... action
		setPopupMenuData(menuData);
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Remove_Tag"));

	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		removeTag(context);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		tagCount = 0;
		if (!(context is VTMatchContext)) {
			return false;
		}

		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return false;
		}

		tagCount = calculateTagCount(matches);
		return tagCount > 0;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return false;
		}
		return true;
	}

	private int calculateTagCount(List<VTMatch> matches) {
		int count = 0;
		foreach (VTMatch match in matches) {
			VTMatchTag tag = match.getTag();
			if (tag != null && tag != VTMatchTag.UNTAGGED) {
				count++;
			}
		}
		return count;
	}

	private void removeTag(ActionContext context) {
		VTMatchContext matchContext = (VTMatchContext) context;

		ComponentProvider componentProvider = matchContext.getComponentProvider();
		JComponent component = componentProvider.getComponent();

		string message = "1 tag?";
		if (tagCount > 1) {
			message = tagCount + " tags?";
		}

		int choice =
			OptionDialog.showYesNoDialog(component, "Remove Match Tag?", "Remove " + message);
		if (choice == OptionDialog.NO_OPTION) {
			return;
		}

		List<VTMatch> matches = matchContext.getSelectedMatches();
		ClearMatchTagTask task = new ClearMatchTagTask(matchContext.getSession(), matches);
		new TaskLauncher(task, component);
	}
}
